END_VAR
VAR CONSTANT
    SOURCE_NAME     : STRING(50) := 'FB_MlPosAbs';
    NO_JERK_LIMIT   : LREAL := 0.0;     // jerk 0 on both = no jerk limit (trapezoid)
END_VAR

ST.xhtml:
IF bSwitchOn <> _bSent THEN
    _stCmd.In.AxisName := sAxisName;
    _stCmd.In.Source   := SOURCE_NAME;
    _stCmd.In.SwitchOn := bSwitchOn;
    _bRejected := NOT ML_AxsPower(Data := _stCmd);
    _bSent     := bSwitchOn;
END_IF

// Outputs
bError := _bRejected;

IF bExecute AND NOT _bIssued THEN
    _stCmd.In.AxisName := sAxisName;
    _stCmd.In.Source   := SOURCE_NAME;
    _bAccepted := ML_AxsReset(Data := _stCmd);
    _bIssued   := TRUE;
ELSIF NOT bExecute THEN
    _bIssued   := FALSE;
    _bAccepted := FALSE;
END_IF

// Outputs
bDone  := _bIssued AND _bAccepted;
bError := _bIssued AND NOT _bAccepted;

